{
  "name": "opencode-dir-tree-tui",
  "version": "1.0.6",
  "description": "OpenCode V2 TUI plugin: VS Code-style file tree in the sidebar with git status coloring and click-to-open",
  "license": "MIT",
  "type": "module",
  "author": "aihaipeng",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/aihaipeng/opencode-dir-tree-tui.git"
  },
  "bugs": {
    "url": "https://github.com/aihaipeng/opencode-dir-tree-tui/issues"
  },
  "homepage": "https://github.com/aihaipeng/opencode-dir-tree-tui#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "plugin",
    "file-tree",
    "opentui"
  ],
  "files": [
    "index.ts",
    "tui.tsx",
    "dist",
    "README.md",
    "README.zh-CN.md",
    "LICENSE"
  ],
  "exports": {
    ".": "./index.ts",
    "./tui": "./dist/tui.js"
  },
  "engines": {
    "opencode": ">=2.0.0"
  },
  "scripts": {
    "build": "bun run typecheck && bun scripts/build.ts",
    "test": "bun scripts/test.ts --preload @opentui/solid/preload",
    "test:package": "bun run build && bun scripts/test-package.ts",
    "typecheck": "tsc --noEmit",
    "prepack": "bun run build"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.16"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.10",
    "@opentui/solid": ">=0.5.10",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opentui/core": "^0.5.10",
    "@opentui/solid": "^0.5.10",
    "solid-js": "^1.9.0",
    "typescript": "^5.8.2"
  }
}
